new file mode 100644
index 0000000..b14107b
--- /dev/null
+++ b/source/core/utils/record-events.ts
@@ -0,0 +1,40 @@
+import type {EventEmitter} from 'node:events';
+
+export type EventRecord = {
+	name: string | symbol;
+	arguments: unknown[];
+};
+
+export default function recordEvents(source: EventEmitter, names: ReadonlyArray<string | symbol>, capacity: number): {records: EventRecord[]; dispose: () => void} {
+	if (!Number.isInteger(capacity) || capacity < 0) {
+		throw new RangeError('Capacity must be a non-negative integer');
+	}
+
+	const records: EventRecord[] = [];
+	const listeners = names.map(name => {
+		const listener = (...arguments_: unknown[]) => {
+			if (capacity === 0) {
+				return;
+			}
+
+			records.push({name, arguments: arguments_});
+			if (records.length > capacity) {
+				records.splice(0, records.length - capacity);
+			}
+		};
+
+		source.on(name, listener);
+		return {name, listener};
+	});
+
+	return {
+		records,
+		dispose() {
+			for (const {name, listener} of listeners) {
+				source.off(name, listener);
+			}
+
+			listeners.length = 0;
+		},
+	};
+}
diff --git a/test/record-events.ts b/test/record-events.ts
new file mode 100644
index 0000000..e05a393
--- /dev/null
+++ b/test/record-events.ts
@@ -0,0 +1,77 @@
+import {EventEmitter} from 'node:events';
+import test from 'ava';
+import recordEvents from '../source/core/utils/record-events.js';
+
+test('records events chronologically across names and evicts oldest entries', t => {
+	const source = new EventEmitter();
+	const symbol = Symbol('event');
+	const journal = recordEvents(source, ['data', symbol], 2);
+	const {records} = journal;
+	const value = {};
+	source.emit('data', value, 1);
+	source.emit(symbol);
+	t.deepEqual(records, [{name: 'data', arguments: [value, 1]}, {name: symbol, arguments: []}]);
+	t.is(records[0].arguments[0], value);
+	source.emit('data', 'last');
+	t.is(journal.records, records);
+	t.deepEqual(records, [{name: symbol, arguments: []}, {name: 'data', arguments: ['last']}]);
+	journal.dispose();
+});
+
+test('zero capacity and empty names record nothing', t => {
+	const source = new EventEmitter();
+	const zero = recordEvents(source, ['data'], 0);
+	const empty = recordEvents(source, [], 2);
+	source.emit('data', 1);
+	t.deepEqual(zero.records, []);
+	t.deepEqual(empty.records, []);
+	zero.dispose();
+	zero.dispose();
+	empty.dispose();
+	t.is(source.listenerCount('data'), 0);
+});
+
+test('invalid capacities throw before adding any listener', t => {
+	for (const capacity of [-1, 0.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY]) {
+		const source = new EventEmitter();
+		let registrations = 0;
+		source.on('newListener', () => registrations++);
+		t.throws(() => recordEvents(source, ['data', 'error'], capacity), {instanceOf: RangeError, message: 'Capacity must be a non-negative integer'});
+		t.is(registrations, 0);
+	}
+});
+
+test('dispose removes only its own listeners, including duplicate names', t => {
+	const source = new EventEmitter();
+	const existing = () => {};
+	source.on('data', existing);
+	const journal = recordEvents(source, ['data', 'data', 'error'], 5);
+	t.is(source.listenerCount('data'), 3);
+	t.is(source.listenerCount('error'), 1);
+	source.emit('error', new Error('recorded'));
+	t.is(journal.records.length, 1);
+	journal.dispose();
+	journal.dispose();
+	t.deepEqual(source.listeners('data'), [existing]);
+	t.is(source.listenerCount('error'), 0);
+	source.emit('data');
+	t.is(journal.records.length, 1);
+});
+
+test('never emits or forwards events and does not handle unrequested errors', t => {
+	const source = new EventEmitter();
+	const journal = recordEvents(source, ['data'], 2);
+	const emit = source.emit.bind(source);
+	source.emit = () => {
+		t.fail('recording must not emit');
+
+		return false;
+	};
+
+	emit('data', 1);
+	t.deepEqual(journal.records, [{name: 'data', arguments: [1]}]);
+	t.is(source.listenerCount('error'), 0);
+	const error = new Error('unhandled');
+	t.throws(() => emit('error', error), {is: error});
+	journal.dispose();
+});
